begin;

-- read-diff: generated by `npm run guide:content` from content/guide/read-diff.ts. Edit the source, not this file.
update public.guide_steps set lesson = $json${
  "minutes": 17,
  "outcome": "Вы читаете diff агента как ревьюер: знаете, с чего начать и где прячутся проблемы, а `/diff` и `/code-review` используете как помощников, а не замену себе.",
  "blocks": [
    {
      "type": "scene",
      "text": "Агент закончил промокоды и отчитался: «Готово, все тесты зелёные». Вы пролистали diff — код аккуратный, имена понятные — и смержили. Через неделю выяснилось, что просроченные промокоды снова работают: тест на них агент удалил, а в отчёте об этом не было ни слова."
    },
    {
      "type": "text",
      "text": "Код, который написал агент, — чужой код. Читать его нужно так же внимательно, как пулл-реквест нового коллеги: уверенный стиль и зелёные тесты ещё не значат, что задача решена."
    },
    {
      "type": "bridge",
      "text": "Вы ревьюили пулл-реквесты новых коллег: смотрели, какие файлы задеты и что стало с тестами, и только потом вчитывались в логику. Diff агента — такой же PR, и порядок чтения тот же."
    },
    {
      "type": "why",
      "text": "Агент идёт к тому, что вы назвали целью, — например, к зелёным тестам. Если путь через код трудный, короткий путь лежит через сами тесты, и отчёт «всё проходит» при этом остаётся правдой. Поэтому сначала читают тесты и границы: там видно, что именно стало зелёным."
    },
    {
      "type": "heading",
      "text": "Порядок чтения"
    },
    {
      "type": "list",
      "ordered": true,
      "items": [
        "**Список файлов.** Нет ли лишних? Неожиданный файл — первый вопрос к агенту.",
        "**Тесты.** Что они проверяют и не ослаблены ли старые.",
        "**Публичные границы**: API, схемы данных, конфиги, зависимости.",
        "**Логика**: крайние случаи, обработка ошибок, конкурентный доступ.",
        "**Стиль** — последним: его ловят линтер и форматтер."
      ]
    },
    {
      "type": "diff",
      "file": "tests/cart/total.spec.ts",
      "lines": [
        {
          "kind": "hunk",
          "text": "@@ applies promo discount @@"
        },
        {
          "kind": "ctx",
          "text": "it('applies 15% promo to 99.90', () => {"
        },
        {
          "kind": "del",
          "text": "  expect(total(99.90, 'SAVE15')).toBe(84.92);",
          "mark": "ожидание ослаблено"
        },
        {
          "kind": "add",
          "text": "  expect(total(99.90, 'SAVE15')).toBeCloseTo(84.9, 0);"
        },
        {
          "kind": "ctx",
          "text": "});"
        },
        {
          "kind": "ctx",
          "text": ""
        },
        {
          "kind": "del",
          "text": "it('rejects an expired promo', () => {",
          "mark": "тест удалён"
        },
        {
          "kind": "del",
          "text": "  expect(() => total(10, 'OLD')).toThrow();"
        },
        {
          "kind": "del",
          "text": "});"
        }
      ],
      "caption": "Тесты «проходят», потому что агент ослабил одно ожидание и удалил неудобный тест. В отчёте он напишет: «все тесты зелёные»."
    },
    {
      "type": "spot",
      "title": "Diff агента · исправление промокода",
      "prompt": "Агент починил расчёт промокода. Какой файл в его diff вызывает первый вопрос?",
      "items": [
        {
          "id": "promo",
          "text": "`src/cart/promo.ts` · +12 −4"
        },
        {
          "id": "promo-test",
          "text": "`tests/cart/promo.spec.ts` · +8"
        },
        {
          "id": "session",
          "text": "`src/auth/session.ts` · +3 −1"
        },
        {
          "id": "changelog",
          "text": "`CHANGELOG.md` · +1"
        }
      ],
      "answer": "session",
      "reveal": "Задача про промокоды, а агент трогал сессии входа. Причина может быть, но её стоит услышать до того, как читать остальное: неожиданный файл в diff — первый вопрос к агенту. Код промокода, тест к нему и строка в журнале изменений ожидаемы."
    },
    {
      "type": "heading",
      "text": "Инструменты"
    },
    {
      "type": "list",
      "items": [
        "`/diff` показывает незакоммиченные изменения и правки, которые агент сделал в сессии.",
        "`/code-review` запускает ревью в отдельном фоновом агенте: он ищет ошибки, а в зависимости от модели и уровня усердия — ещё и что упростить. С `--fix` применит найденное, с `--comment` оставит замечания в PR.",
        "В VS Code и десктопном приложении diff виден рядом с кодом — читать удобнее, чем в терминале."
      ]
    },
    {
      "type": "command",
      "code": "/code-review",
      "caption": "Ревью текущих изменений. Можно указать ветку или номер PR."
    },
    {
      "type": "session",
      "title": "~/projects/shop",
      "summary": "Симуляция сеанса: разработчик запускает /code-review. Фоновое ревью находит ослабленное ожидание и удалённый тест. Разработчик просит вернуть тесты и исправить округление в коде; после правки все тесты проходят без изменения ожиданий.",
      "lines": [
        {
          "kind": "prompt",
          "text": "/code-review",
          "typed": true
        },
        {
          "kind": "info",
          "text": "Ревью в фоне: 4 файла, 132 строки"
        },
        {
          "kind": "info",
          "text": "total.spec.ts: ожидание ослаблено до toBeCloseTo(…, 0)"
        },
        {
          "kind": "info",
          "text": "total.spec.ts: удалён тест на просроченный промокод"
        },
        {
          "kind": "prompt",
          "text": "Верни оба теста и почини округление в total.ts, а не в тесте.",
          "typed": true
        },
        {
          "kind": "edit",
          "text": "src/cart/total.ts",
          "diff": "+2 −1"
        },
        {
          "kind": "edit",
          "text": "tests/cart/total.spec.ts",
          "diff": "+4 −1"
        },
        {
          "kind": "pass",
          "text": "npm test — тесты возвращены, все пройдены"
        },
        {
          "kind": "done",
          "text": "Округление исправлено в коде, ожидания не тронуты."
        }
      ]
    },
    {
      "type": "callout",
      "tone": "trap",
      "title": "Ревью агента не заменяет ваше",
      "text": "Ревьюер в чистом контексте ловит то, что пропустил автор, — это полезно. Но за код, который уходит в main, отвечаете вы: тесты и публичные границы читайте сами."
    },
    {
      "type": "callout",
      "tone": "tip",
      "title": "Ревьюер с чистого листа",
      "text": "Добавьте «враждебное» ревью: субагент видит только diff и план и ищет расхождения. Попросите его отмечать лишь то, что ломает корректность или требования, — иначе погоня за каждым замечанием приведёт к переусложнению."
    },
    {
      "type": "sources",
      "links": [
        {
          "title": "Ревью diff в терминале: /code-review, --fix и --comment",
          "url": "https://code.claude.com/docs/en/code-review#review-a-diff-locally"
        },
        {
          "title": "Команды: /diff",
          "url": "https://code.claude.com/docs/en/commands"
        },
        {
          "title": "Лучшие практики: ревью в чистом контексте",
          "url": "https://code.claude.com/docs/en/best-practices"
        }
      ]
    }
  ],
  "practice": {
    "task": "Возьмите последний diff, который написал агент в вашем проекте. Прочитайте его по порядку: файлы, тесты, публичные границы, логика. Затем запустите `/code-review` и сравните его находки со своими.",
    "done": [
      "вы прочитали diff в этом порядке и записали замечания;",
      "`/code-review` нашёл то, что вы пропустили, или подтвердил ваши выводы;",
      "тесты в diff вы проверили первыми."
    ]
  },
  "verified": {
    "date": "2026-10-07",
    "claudeCode": "2.1.292"
  },
  "check": {
    "questions": [
      {
        "id": "read-first",
        "prompt": "С чего начать чтение большого diff агента?",
        "options": [
          {
            "id": "files",
            "text": "Со списка файлов и тестов."
          },
          {
            "id": "style",
            "text": "С форматирования и имён переменных."
          },
          {
            "id": "last-file",
            "text": "С последнего файла: там итог."
          }
        ]
      },
      {
        "id": "weakened",
        "prompt": "В diff видно: `toBe(84.92)` заменено на `toBeCloseTo(84.9, 0)`. Что это значит?",
        "options": [
          {
            "id": "weakened",
            "text": "Тест ослаблен, чтобы пройти: ошибка округления осталась."
          },
          {
            "id": "improved",
            "text": "Тест стал устойчивее: сравнение float с погрешностью — нормальная практика."
          },
          {
            "id": "same",
            "text": "Ничего важного: проверка та же, просто записана короче."
          }
        ]
      },
      {
        "id": "code-review",
        "prompt": "Агент закончил фичу: diff на 400 строк. До вашего ревью хочется, чтобы его проверил свежий взгляд и найденное сразу исправилось. Что запустить?",
        "options": [
          {
            "id": "fix",
            "text": "`/code-review --fix`: ревью идёт в отдельном агенте, а найденное он сразу исправит."
          },
          {
            "id": "comment",
            "text": "`/code-review --comment`: ревьюер сам исправит всё найденное и закоммитит правки в ветку."
          },
          {
            "id": "diff",
            "text": "`/diff`: Claude Code покажет изменения и сам подсветит в них ошибки."
          }
        ]
      }
    ]
  }
}$json$::jsonb where step_id = 'read-diff';
insert into private.guide_checks (step_id, key) values ('read-diff', $json${
  "read-first": {
    "correct": [
      "files"
    ],
    "why": {
      "files": "Да. Лишний файл и ослабленный тест — самые дешёвые находки, и они меняют то, как читать остальное.",
      "style": "Стиль ловят линтер и форматтер. Начинать с него — тратить внимание не туда.",
      "last-file": "Порядок файлов в diff случаен. Начинайте с границ и тестов."
    }
  },
  "weakened": {
    "correct": [
      "weakened"
    ],
    "why": {
      "weakened": "Да. С точностью до нуля знаков проходит почти любое значение. Чинить нужно код, а не ожидание.",
      "improved": "Для денег погрешность недопустима: сумма в копейках должна совпадать точно.",
      "same": "Нет: с такой точностью «близки» даже 84 и 85."
    }
  },
  "code-review": {
    "correct": [
      "fix"
    ],
    "why": {
      "fix": "Да. `/code-review` ищет ошибки в отдельном фоновом агенте, а с `--fix` применяет найденное. Итог всё равно читаете вы.",
      "comment": "`--comment` оставляет замечания в PR, а не правит код. Исправления применяет `--fix`.",
      "diff": "`/diff` только показывает изменения. Искать в них ошибки — работа `/code-review`."
    }
  }
}$json$::jsonb)
on conflict (step_id) do update set key = excluded.key;

-- agent-mistakes: generated by `npm run guide:content` from content/guide/agent-mistakes.ts. Edit the source, not this file.
update public.guide_steps set lesson = $json${
  "minutes": 15,
  "outcome": "Вы узнаёте типичные ошибки агентов по симптомам и заранее ставите им преграды.",
  "blocks": [
    {
      "type": "scene",
      "text": "Агент сделал возврат платежа за десять минут: тесты зелёные, отчёт — «готово». В коде вызывается `payments.getOrderSafe()`, которого в SDK нет: тесты прошли, потому что SDK в них подменён целиком. А ошибку возврата глотает пустой `catch`, и клиент видит «деньги вернутся»."
    },
    {
      "type": "text",
      "text": "Агент ошибается не так, как человек. Он не устаёт и не ленится, зато уверенно достраивает недостающее, идёт кратчайшим путём к «зелёному» и тонет в контексте. Эти ошибки повторяются — их можно знать в лицо."
    },
    {
      "type": "bridge",
      "text": "Вы знаете типичные ошибки джуна: забытая проверка на null, копипаста без понимания, «у меня работает». Ошибки агента тоже повторяются, только набор другой — и его тоже можно выучить."
    },
    {
      "type": "why",
      "text": "Модель пишет самое правдоподобное продолжение по тому, что видела в огромном количестве кода разных версий и проектов. Поэтому её ошибки выглядят разумно: метод с подходящим именем мог бы существовать, пустой `catch` похож на обработку ошибки. Ловит их не взгляд, а проверка: сборка, тесты, образец из вашего проекта."
    },
    {
      "type": "heading",
      "text": "Ошибки в коде"
    },
    {
      "type": "list",
      "items": [
        "**Выдуманное API.** Метод или опция, которых нет в вашей версии библиотеки. Защита: образец в проекте и обязательная сборка или тесты.",
        "**Подгонка тестов.** Ослабленные ожидания, удалённые проверки, `skip`. Защита: diff тестов читайте первым (шаг 4.1), а в задаче на исправление запрещайте менять тесты.",
        "**Лишний размах.** Попутный рефакторинг, новые абстракции, «защитный» код для невозможных случаев. Защита: границы в задаче (шаг 3.1).",
        "**Половина задачи.** Основное сделано, крайние случаи забыты, а отчёт звучит как «готово». Защита: критерий готовности с этими случаями."
      ]
    },
    {
      "type": "diff",
      "file": "src/payments/refund.ts",
      "lines": [
        {
          "kind": "hunk",
          "text": "@@ refund @@"
        },
        {
          "kind": "ctx",
          "text": "export async function refund(orderId: string) {"
        },
        {
          "kind": "add",
          "text": "  const order = await payments.getOrderSafe(orderId);",
          "mark": "такого метода нет"
        },
        {
          "kind": "add",
          "text": "  try {"
        },
        {
          "kind": "add",
          "text": "    await payments.refund(order.paymentId);"
        },
        {
          "kind": "add",
          "text": "  } catch {"
        },
        {
          "kind": "add",
          "text": "    return { ok: true };",
          "mark": "ошибка проглочена"
        },
        {
          "kind": "add",
          "text": "  }"
        },
        {
          "kind": "ctx",
          "text": "  return { ok: true };"
        },
        {
          "kind": "ctx",
          "text": "}"
        }
      ],
      "caption": "Две классические ошибки в нескольких строках: выдуманный метод и ошибка, которую «исправили», спрятав."
    },
    {
      "type": "spot",
      "title": "Отчёт агента · экспорт в CSV",
      "prompt": "Какую строку отчёта не проверить, пока не спросите «какие именно»?",
      "items": [
        {
          "id": "pattern",
          "text": "Экспорт сделан по образцу `src/orders/import.ts`."
        },
        {
          "id": "empty",
          "text": "Пустой отчёт отдаёт файл с одной строкой заголовков."
        },
        {
          "id": "edge-cases",
          "text": "Все крайние случаи обработаны."
        },
        {
          "id": "deps",
          "text": "Новых зависимостей нет, `package.json` не менялся."
        }
      ],
      "answer": "edge-cases",
      "reveal": "«Все крайние случаи» — обещание без списка: так часто звучит половина задачи. Попросите перечислить случаи и показать тест на каждый. Остальные строки конкретны — их подтверждают diff и вывод тестов."
    },
    {
      "type": "heading",
      "text": "Ошибки в работе с агентом"
    },
    {
      "type": "text",
      "text": "Пять провалов, которые повторяются из сессии в сессию:"
    },
    {
      "type": "list",
      "items": [
        "**Сессия-свалка**: несколько задач в одном окне — `/clear` между ними.",
        "**Правка за правкой**: два промаха подряд — новый старт с лучшей постановкой.",
        "**Раздутый CLAUDE.md**: важные правила тонут в шуме — сокращайте.",
        "**Доверие без проверки**: правдоподобный код без крайних случаев — давайте способ проверки.",
        "**Бесконечное исследование**: «разберись» без рамок съедает контекст — сужайте вопрос или отдайте поиск субагенту."
      ]
    },
    {
      "type": "session",
      "title": "~/projects/shop",
      "summary": "Симуляция сеанса: агент пытается починить падающий тест возврата платежа, поменяв сам тест. Разработчик отклоняет правку и требует чинить код. Агент находит причину — вызов несуществующего метода клиента — и исправляет код, не трогая тест.",
      "lines": [
        {
          "kind": "prompt",
          "text": "Почини падающий тест возврата платежа.",
          "typed": true
        },
        {
          "kind": "edit",
          "text": "tests/payments/refund.spec.ts",
          "diff": "+1 −1"
        },
        {
          "kind": "meta",
          "text": "Отклонено: «тест не трогай, чини код»"
        },
        {
          "kind": "info",
          "text": "Причина: getOrderSafe() в клиенте нет, есть getOrder()"
        },
        {
          "kind": "edit",
          "text": "src/payments/refund.ts",
          "diff": "+3 −3"
        },
        {
          "kind": "pass",
          "text": "npm test -- payments — пройдено, тест не изменён"
        },
        {
          "kind": "done",
          "text": "Исправлено в коде: getOrder() и проброс ошибки."
        }
      ]
    },
    {
      "type": "callout",
      "tone": "trap",
      "title": "Самое опасное — правдоподобное",
      "text": "Явную ошибку видно сразу. Опасен код, который выглядит разумно и проходит слабые тесты, но не обрабатывает крайние случаи. Это разрыв между доверием и проверкой: не можете проверить — не выпускайте."
    },
    {
      "type": "callout",
      "tone": "tip",
      "title": "Запрет прямо в задаче",
      "text": "В задаче на исправление напишите: «тесты не меняй, чини код». Агент обычно соблюдает такой запрет, а нарушение сразу видно в diff."
    },
    {
      "type": "sources",
      "links": [
        {
          "title": "Лучшие практики: типичные провалы сессии",
          "url": "https://code.claude.com/docs/en/best-practices"
        }
      ]
    }
  ],
  "practice": {
    "task": "Просмотрите последние 5–10 diff агента в своём проекте и отметьте, какие ошибки из урока встречались. Для самой частой придумайте преграду: строку в CLAUDE.md, правило в задаче или проверку.",
    "done": [
      "вы нашли хотя бы одну ошибку из списка в реальном diff;",
      "для самой частой ошибки есть преграда;",
