        {
          "kind": "edit",
          "text": "tests/cart/promo.spec.ts",
          "diff": "+36"
        },
        {
          "kind": "info",
          "text": "npm test -- promo — 3 теста упали, как и ожидалось"
        },
        {
          "kind": "prompt",
          "text": "Закоммить тесты. Теперь реализация, тесты не меняй.",
          "typed": true
        },
        {
          "kind": "info",
          "text": "git commit -m \"test: pin promo code rules\""
        },
        {
          "kind": "edit",
          "text": "src/cart/promo.ts",
          "diff": "+41"
        },
        {
          "kind": "pass",
          "text": "npm test -- promo — 3 из 3, тесты не изменены"
        },
        {
          "kind": "done",
          "text": "Готово: поведение соответствует договору."
        }
      ]
    },
    {
      "type": "spot",
      "title": "Тесты на промокоды · черновик",
      "prompt": "Какой тест пройдёт при любой реализации?",
      "items": [
        {
          "id": "save15",
          "text": "SAVE15 к сумме 99,90 даёт 84,92."
        },
        {
          "id": "expired",
          "text": "Просроченный промокод отклоняется с ошибкой."
        },
        {
