    ]
  },
  "verified": {
    "date": "2026-10-07",
    "claudeCode": "2.1.292"
  },
  "check": {
    "questions": [
      {
        "id": "green-at-once",
        "prompt": "Агент написал тест на баг, и тест сразу прошёл. Что это значит?",
