-- security-deps: generated by `npm run guide:content` from content/guide/security-deps.ts. Edit the source, not this file.
update public.guide_steps set lesson = $json${
  "minutes": 16,
  "outcome": "Вы не даёте агенту раскрыть секреты, пропустить уязвимость или протащить лишнюю зависимость и знаете, какие проверки Claude Code берёт на себя.",
  "blocks": [
    {
      "type": "scene",
      "text": "Агент добавил страницу заказа: вход проверяется, тесты зелёные, код аккуратный. Через месяц в логах базы нашёлся запрос с `1 or 1=1` вместо номера заказа — и ответ со всеми заказами магазина. Номер из адреса шёл в SQL как есть."
    },
    {
      "type": "text",
      "text": "Агент работает с правами вашего терминала: видит те же файлы, запускает те же команды и ставит пакеты. Безопасность здесь — это границы (шаг 1.2) плюс внимательное ревью тех мест, где ошибка стоит дороже всего."
    },
    {
      "type": "bridge",
      "text": "Новому подрядчику вы не даёте боевые ключи и доступ ко всему подряд: тестовый стенд, нужные права, ревью перед выкладкой. Агенту нужны те же границы."
    },
    {
      "type": "why",
      "text": "Для агента «работает» значит, что тесты прошли и ответ правильный. Проверка прав, обработка ввода и судьба токена в логах в такой критерий не входят, пока вы их не назвали. Поэтому безопасность задают извне: запретами в настройках, вопросами на ревью и отдельной проверкой `/security-review`."
    },
    {
      "type": "heading",
      "text": "Секреты"
    },
    {
      "type": "list",
      "items": [
        "Запретите чтение секретов в `.claude/settings.json`: `Read(./.env)`, `Read(./secrets/**)`. Агенту не нужны боевые ключи, чтобы писать код.",
        "Не вставляйте токены в запрос: они останутся в истории сессии.",
        "Нужен доступ к сервису — дайте отдельный тестовый ключ с минимальными правами."
      ]
    },
    {
      "type": "heading",
      "text": "Что проверять в diff"
    },
    {
      "type": "list",
      "items": [
        "**Ввод пользователя**: не попадает ли он в SQL, команды или HTML без обработки.",
        "**Права**: проверяется ли, что пользователь вправе сделать это действие, а не только что он вошёл.",
        "**Секреты в коде**: ключи, токены и пароли в исходниках или логах.",
        "**Новые зависимости**: у каждой библиотеки в diff должна быть причина."
      ]
    },
    {
      "type": "diff",
      "file": "src/api/orders.ts",
      "lines": [
        {
          "kind": "hunk",
          "text": "@@ GET /orders/:id @@"
        },
        {
          "kind": "ctx",
          "text": "router.get('/orders/:id', auth, async (req, res) => {"
        },
        {
          "kind": "add",
          "text": "  const order = await db.query(`select * from orders where id = ${req.params.id}`);",
          "mark": "SQL-инъекция"
        },
        {
          "kind": "add",
          "text": "  res.json(order);",
          "mark": "чужой заказ виден"
        },
        {
          "kind": "ctx",
          "text": "});"
        }
      ],
      "caption": "Вход проверен, а права — нет: любой вошедший прочитает чужой заказ, подставив id. А id ещё и попадает в SQL как есть."
    },
    {
      "type": "spot",
      "title": "Diff агента · вход по ссылке",
      "prompt": "Какую строку этого diff вы не пропустите на ревью?",
      "items": [
        {
          "id": "find",
          "text": "`const user = await users.findByEmail(email);`"
        },
        {
          "id": "log",
          "text": "`logger.info(\"link sent\", { email, token });`"
        },
        {
          "id": "unknown",
          "text": "`if (!user) return res.status(200).end();`"
        },
        {
          "id": "send",
          "text": "`await mailer.send(email, linkFor(token));`"
        }
      ],
      "answer": "log",
      "reveal": "Токен входа попал в лог: любой, кто читает логи, войдёт под чужим именем. Логируйте факт отправки, но не сам токен. Остальные строки в порядке — даже ответ 200 для неизвестного адреса: так никто не узнает, какие адреса зарегистрированы."
    },
    {
      "type": "heading",
      "text": "Проверка безопасности"
    },
    {
      "type": "command",
      "code": "/security-review",
      "caption": "Сравнит вашу ветку с основной и поищет типичные уязвимости: инъекции, ошибки авторизации, утечки данных."
    },
    {
      "type": "session",
      "title": "~/projects/shop",
      "summary": "Симуляция сеанса: /security-review находит в ветке SQL-инъекцию и отсутствие проверки владельца заказа. Разработчик просит исправить обе проблемы и добавить тест на чужой заказ; после правки тест подтверждает, что чужой заказ недоступен.",
      "lines": [
